BEGIN;
ALTER TABLE "AuditLog" DROP CONSTRAINT "AuditLog_action";
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_action" CHECK (action IN ('ACCOUNT_REGISTERED','EMAIL_VERIFIED','EMAIL_CORRECTED','PASSWORD_RESET','TOKEN_ROTATED','INVITATION_CREATED','INVITATION_ACCEPTED','INVITATION_REVOKED','INVITATION_ROTATED','ACCESS_GRANTED','ACCESS_RECONCILED','ACCESS_REMOVED','STUDIO_APPROVAL_CHANGED','REGISTRATION_APPROVAL_CHANGED','IMAGE_REPLACED','SESSION_REVOKED','ONBOARDING_SAVED','ONBOARDING_CANCELLED'));
COMMIT;
